import plistlib
d=plistlib.load(open('ad.plist','rb'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,p+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,p+f'[{i}]')
    else:
        pl=p.lower()
        if any(s in pl for s in ('sign','cert','authority','identity','team','codesign-verify','codesign-display')) and 'codesign-allocate' not in pl:
            s=repr(o)
            print(p, '=>', s[:300])
walk(d)
EOF

