import plistlib
d=plistlib.load(open('ad.plist','rb'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if k in ('codesign-allocate-result',) or 'launch' in str(v)[:0]:
                print(p+'/'+k); 
                for kk,vv in v.items(): print('   ',kk,':',repr(vv)[:400])
